-- =====================================================================
-- WorkLink: datos de DEMO (generado). Re-ejecutable: borra y recrea los datos @demo-worklink.test
-- Cuentas demo (contraseña de todas: Demo1234):
--   demo_postulante, demo_freelancer, demo_empresa, demo_recruiter, demo_cliente
-- Resto de usuarios: <rol>01..<rol>19 (ej. postulante07, freelancer12), misma contraseña.
-- =====================================================================
SET NAMES utf8mb4;
START TRANSACTION;
CREATE TEMPORARY TABLE demo_perfil AS SELECT perfil_id FROM perfil WHERE email LIKE '%@demo-worklink.test';
CREATE TEMPORARY TABLE demo_emp AS SELECT employee_id FROM employee WHERE perfil_id IN (SELECT perfil_id FROM demo_perfil);
CREATE TEMPORARY TABLE demo_cli AS SELECT cliente_particular_id FROM cliente_particular WHERE perfil_id IN (SELECT perfil_id FROM demo_perfil);
CREATE TEMPORARY TABLE demo_empresa AS SELECT empresa_id FROM empresa WHERE perfil_id IN (SELECT perfil_id FROM demo_perfil);
CREATE TEMPORARY TABLE demo_proy AS SELECT proyecto_id FROM proyecto WHERE cliente_id IN (SELECT cliente_particular_id FROM demo_cli);
CREATE TEMPORARY TABLE demo_vac AS SELECT vacante_id FROM vacante WHERE empresa_id IN (SELECT empresa_id FROM demo_empresa);
CREATE TEMPORARY TABLE demo_cal AS SELECT calificacion_id FROM calificacion_proyecto WHERE proyecto_id IN (SELECT proyecto_id FROM demo_proy);
DELETE FROM calificacion_usuario WHERE calificacion_id IN (SELECT calificacion_id FROM demo_cal) OR perfil_id IN (SELECT perfil_id FROM demo_perfil);
DELETE FROM calificacion_proyecto WHERE proyecto_id IN (SELECT proyecto_id FROM demo_proy);
DELETE FROM pagos WHERE proyecto_id IN (SELECT proyecto_id FROM demo_proy);
DELETE FROM hito_proyecto WHERE proyecto_id IN (SELECT proyecto_id FROM demo_proy);
DELETE FROM postulacion_proyecto WHERE proyecto_id IN (SELECT proyecto_id FROM demo_proy) OR employee_id IN (SELECT employee_id FROM demo_emp);
DELETE FROM proyecto_habilidades WHERE proyecto_id IN (SELECT proyecto_id FROM demo_proy);
DELETE FROM proyecto WHERE proyecto_id IN (SELECT proyecto_id FROM demo_proy);
DELETE FROM entrevista WHERE postulacion_id IN (SELECT postulacion_id FROM postulacion_vacante WHERE vacante_id IN (SELECT vacante_id FROM demo_vac) OR postulante_id IN (SELECT employee_id FROM demo_emp));
DELETE FROM postulacion_vacante WHERE vacante_id IN (SELECT vacante_id FROM demo_vac) OR postulante_id IN (SELECT employee_id FROM demo_emp);
DELETE FROM vacante_etiquetas WHERE vacante_id IN (SELECT vacante_id FROM demo_vac);
DELETE FROM vacante WHERE vacante_id IN (SELECT vacante_id FROM demo_vac);
DELETE FROM recruiter WHERE perfil_id IN (SELECT perfil_id FROM demo_perfil) OR empresa_id IN (SELECT empresa_id FROM demo_empresa);
DELETE FROM empresa WHERE empresa_id IN (SELECT empresa_id FROM demo_empresa);
DELETE FROM freelancer_medios_cobro WHERE freelancer_id IN (SELECT perfil_id FROM demo_perfil);
DELETE FROM portfolio WHERE employee_id IN (SELECT employee_id FROM demo_emp);
DELETE FROM experiencia WHERE employee_id IN (SELECT employee_id FROM demo_emp);
DELETE FROM employee_habilidad WHERE employee_id IN (SELECT employee_id FROM demo_emp);
DELETE FROM employee WHERE employee_id IN (SELECT employee_id FROM demo_emp);
DELETE FROM cliente_particular WHERE cliente_particular_id IN (SELECT cliente_particular_id FROM demo_cli);
DELETE FROM perfil WHERE perfil_id IN (SELECT perfil_id FROM demo_perfil);
DROP TEMPORARY TABLE demo_perfil, demo_emp, demo_cli, demo_empresa, demo_proy, demo_vac, demo_cal;
COMMIT;
-- Totales generados: 62 proyectos, 86 hitos, 67 pagos, 46 calificaciones, 62 vacantes, 100 postulaciones a vacantes, 35 entrevistas
